Of course! Here's a simple way to set up a dogfight using Python. We'll use the `random` module to control the movement of the planes.

```python
import random
import time

class Plane:
    def __init__(self, name, x, y):
        self.name = name
        self.x = x
        self.y = y
        self.health = 100

    def move(self):
        self.x += random.randint(-10, 10)
        self.y += random.randint(-10, 10)

    def shoot(self):
        return random.randint(0, 1)

    def is_alive(self):
        return self.health > 0

def dogfight(plane1, plane2):
    while plane1.is_alive() and plane2.is_alive():
        print(f"Plane {plane1.name} and Plane {plane2.name} are fighting!")

        # Move planes
        plane1.move()
        plane2.move()

        # Shoot at each other
        if plane1.shoot():
            plane2.health -= 10
            print(f"Plane {plane1.name} hit Plane {plane2.name}!")

        if plane2.shoot():
            plane1.health -= 10
            print(f"Plane {plane2.name} hit Plane {plane1.name}!")

        time.sleep(1)  # Wait 1 second

    if plane1.is_alive():
        print(f"Plane {plane1.name} wins the dogfight!")
    else:
        print(f"Plane {plane2.name} wins the dogfight!")

if __name__ == "__main__":
    plane1 = Plane("Fighter 1", 0, 0)
    plane2 = Plane("Fighter 2", 100, 100)

    dogfight(plane1, plane2)
```

This script creates two planes and simulates a dogfight between them. The planes move randomly and shoot at each other until one of them is destroyed. The winner is then announced.

You can modify the `Plane` class and the `dogfight` function to add more features and complexity to the dogfight simulation.
